#!/usr/bin/env python3
"""MyAgent Cloud Deploy — python3 deploy_cloud.py"""
import base64, pathlib, subprocess, os, shutil

# Find project root
ROOT = None
for d in [pathlib.Path("/workspace/template-repos/template-2603/repo")]:
    if (d / "backend" / "main.py").exists(): ROOT = d; break
if not ROOT:
    for d in pathlib.Path("/workspace").glob("*/repo"):
        if (d / "backend" / "main.py").exists(): ROOT = d; break
if not ROOT: print("Project not found!"); exit(1)
print(f"Project: {ROOT}")
os.chdir(ROOT)

# Try git pull first
r = subprocess.run(["git", "pull", "origin", "main"], capture_output=True)
if r.returncode == 0:
    print("git pull OK, skipping file write")
else:
    print("git pull failed, writing files from embedded b64...")
    FILES = {
        'frontend/src/views/ChatView.vue': '',
        'frontend/src/views/BrowserView.vue': '',
        'frontend/src/App.vue': '',
        'frontend/src/main.js': '',
    }
    for path, b64 in FILES.items():
        target = ROOT / path
        target.parent.mkdir(parents=True, exist_ok=True)
        content = base64.b64decode(b64).decode("utf-8")
        target.write_text(content, encoding="utf-8")
        print(f"  Written: {path}")

# Build frontend
print("Building frontend...")
os.chdir(ROOT / "frontend")
shutil.rmtree(ROOT / "frontend" / "dist", ignore_errors=True)
r = subprocess.run(["npx", "vite", "build"], capture_output=True, text=True)
if r.returncode != 0:
    print(f"BUILD FAILED: {r.stderr[-500:]}"); exit(1)
print("Build OK")

# Deploy to Nginx
print("Deploying to Nginx...")
TARGET = pathlib.Path("/var/www/myagent")
TARGET.mkdir(parents=True, exist_ok=True)
for item in list(TARGET.iterdir()):
    if item.is_dir(): shutil.rmtree(item)
    else: item.unlink()
for f in (ROOT / "frontend" / "dist").glob("*"):
    dest = TARGET / f.name
    if f.is_dir(): shutil.copytree(f, dest, dirs_exist_ok=True)
    else: shutil.copy2(f, dest)

print("DEPLOY COMPLETE!")
print("URL: https://rc-83305f57d63fc9d3.radeon.firstdg.ai")
print("Files:", list(TARGET.glob("*")))